private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}

/// Use a global variable to perform the versioning checks. Swift ensures that
/// the code inside is only computed once.
private var initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 26
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_rustdisk_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if uniffi_rustdisk_core_checksum_func_cancel_active_scan() != 54490 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_delete_item() != 42237 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_get_disk_overview() != 52986 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_purge_items() != 37077 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_run_package_maintenance() != 61134 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_run_terminal_uninstall() != 20983 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_scan_duplicates() != 42897 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_scan_large_files() != 8510 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_scan_large_files_with_options() != 30328 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_scan_project_artifacts() != 23729 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_scan_safe_caches() != 62420 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_rustdisk_core_checksum_func_scan_terminal_packages() != 4589 {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

private func uniffiEnsureInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

